// What the Pod needs; mismatches here cause each stuck phase.
public class PodSpec {
    String imageTag = "v7";          // bad tag -> ImagePullBackOff
    boolean pullSecretPresent = true;
    boolean dbSecretPresent = true;  // missing -> CrashLoopBackOff
    int cpuRequest = 1;              // > node free -> Pending
    int nodeFreeCpu = 2;
    boolean pvcBound = true;         // unbound -> ContainerCreating
    boolean imageExists = true;
}
