package com.bank.diag;

import java.util.logging.Logger;

// Evaluates a PodSpec, prints kubectl-style evidence, and returns the phase.
public class PodDiagnostician {
    private static final Logger log = Logger.getLogger(PodDiagnostician.class.getName());

    public PodPhase diagnose(PodSpec s) {
        // 1. Scheduling: resource requests vs node capacity
        if (s.cpuRequest > s.nodeFreeCpu) {
            log.severe(() -> "describe: FailedScheduling — Insufficient cpu (request "
                    + s.cpuRequest + " > node free " + s.nodeFreeCpu + ")");
            log.info("FIX: lower cpu request OR let Cluster Autoscaler add a node");
            return PodPhase.PENDING;
        }
        // 2. Setup: volume binding
        if (!s.pvcBound) {
            log.severe("describe: Events — Unable to attach volume: PVC not bound");
            log.info("FIX: provision a matching PV / check StorageClass");
            return PodPhase.CONTAINER_CREATING;
        }
        // 3. Image pull: tag + registry creds
        if (!s.imageExists || !s.pullSecretPresent) {
            log.severe(() -> "describe: Failed to pull image nbi/transfer-service:" + s.imageTag
                    + " — " + (!s.imageExists ? "tag not found" : "no imagePullSecret"));
            log.info("FIX: correct tag / push image / attach imagePullSecret");
            return PodPhase.IMAGE_PULL_BACKOFF;
        }
        // 4. App start: missing config/secret -> crash after launch
        if (!s.dbSecretPresent) {
            log.severe("describe: Last State Terminated, Reason: Error, Exit Code: 1");
            log.severe("logs --previous: IllegalStateException: DB_PASSWORD secret not found");
            log.info("FIX: create the db-password Secret and rollout restart");
            return PodPhase.CRASH_LOOP_BACKOFF;
        }
        log.info("describe: Running, all containers Ready");
        return PodPhase.RUNNING;
    }
}
