package com.bank.diag;

import java.math.BigDecimal;
import java.util.logging.*;

public class PodDiagnosticsDemo {
    private static final Logger log = Logger.getLogger(PodDiagnosticsDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        PodDiagnostician doc = new PodDiagnostician();

        // Case 1: Pending (requests too big)
        PodSpec p1 = new PodSpec(); p1.cpuRequest = 4; p1.nodeFreeCpu = 2;
        log.info("Case PENDING -> " + doc.diagnose(p1));

        // Case 2: ContainerCreating (PVC unbound)
        PodSpec p2 = new PodSpec(); p2.pvcBound = false;
        log.info("Case CONTAINER_CREATING -> " + doc.diagnose(p2));

        // Case 3: ImagePullBackOff (bad tag)
        PodSpec p3 = new PodSpec(); p3.imageTag = "v9"; p3.imageExists = false;
        log.info("Case IMAGE_PULL_BACKOFF -> " + doc.diagnose(p3));

        // Case 4: CrashLoopBackOff (missing secret)
        PodSpec p4 = new PodSpec(); p4.dbSecretPresent = false;
        log.info("Case CRASH_LOOP_BACKOFF -> " + doc.diagnose(p4));

        // Healthy Pod: transfer succeeds
        PodSpec ok = new PodSpec();
        if (doc.diagnose(ok) == PodPhase.RUNNING) {
            rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
            log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on healthy pod");
        }
    }
}
